class SnomedService:
    @staticmethod
    def get_concept(cid: str) -> Optional[SnomedConcept]:
        return SNOMED_DATABASE.get(cid.strip())

    @staticmethod
    def search(query: str, tag: Optional[str] = None) -> List[SnomedConcept]:
        q = query.lower().strip()
        return [c for c in SNOMED_DATABASE.values() if (not tag or c.semantic_tag == tag) and (q in c.concept_id or q in c.fully_specified_name.lower())][:50]
